### The Solution

This component uses a simple prop-based approach to switch between `max-w-none` (Full Width) and `max-w-screen-xl` (Centered).

```jsx
import React from 'react';

/**
 * Layout Component
 * @param {Object} props
 * @param {boolean} props.centered - If true, the content is centered with a max-width. 
 * @param {React.ReactNode} props.children - The content to render inside the layout.
 */
export default function Layout({ centered = false, children }) {
  return (
    // 1. Base background style
    <main className="min-h-screen bg-white">
      {/* 
        2. Container Logic: 
           - If centered: adds max-width, padding, and auto margins.
           - If full: adds padding only.
      */}
      <div 
        className={centered 
          ? "mx-auto w-full px-6 py-12 sm:px-8 lg:px-12" 
          : "w-full px-6 py-12 sm:px-8 lg:px-12"
        }
      >
        {/* 
          3. Content Wrapper 
             - Centered variant: Wraps content in a max-width box.
             - Full variant: Passes children directly to the container above.
        */}
        {centered ? (
          <div className="mx-auto max-w-7xl">
            {children}
          </div>
        ) : (
          children
        )}
      </div>
    </main>
  );
}
```

